import{_ as r,I as d,c as i,o as e,a3 as l,b as c,w as o,a as s,J as n,a4 as g,a5 as y,a6 as E,a7 as m,a8 as h}from"./chunks/framework.czLORLkK.js";const S=JSON.parse('{"title":"Zero-Mock 엔터프라이즈 품질 하네스 및 검증 프로토콜","description":"SyncSeries 전사 코어 에이전트 및 공통 모듈에 적용된 Mock 전면 금지, RFC 7807 표준 에러 처리, 4-Cycle 품질 검증 및 자동화 감사 스크립트 명세","frontmatter":{"title":"Zero-Mock 엔터프라이즈 품질 하네스 및 검증 프로토콜","sidebarTitle":"Zero-Mock 품질 하네스","description":"SyncSeries 전사 코어 에이전트 및 공통 모듈에 적용된 Mock 전면 금지, RFC 7807 표준 에러 처리, 4-Cycle 품질 검증 및 자동화 감사 스크립트 명세","head":[["meta",{"name":"keywords","content":"Zero-Mock, 4-Cycle 품질 검증, RFC 7807, Problem Details, verify-zero-mock, 자동화 감사, Fake Normalcy 금지"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ecosystem/zero-mock-harness"}]],"sort":35},"headers":[],"relativePath":"ecosystem/zero-mock-harness.md","filePath":"ko/ecosystem/zero-mock-harness.md","lastUpdated":1793197021000}'),C={name:"ecosystem/zero-mock-harness.md"};function p(f,t,A,k,B,_){const a=d("Mermaid");return e(),i("div",null,[t[1]||(t[1]=l('<h1 id="zero-mock-엔터프라이즈-품질-하네스-및-검증-프로토콜" tabindex="-1">Zero-Mock 엔터프라이즈 품질 하네스 및 검증 프로토콜 <a class="header-anchor" href="#zero-mock-엔터프라이즈-품질-하네스-및-검증-프로토콜" aria-label="Permalink to “Zero-Mock 엔터프라이즈 품질 하네스 및 검증 프로토콜”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">실제 구현 예시 안내</p><p>Testcontainers 기반 실제 Spring Boot 및 PostgreSQL 테스트 코드 작성법은 <a href="/sdk/zero-mock-testing">실환경 기반 테스트 가이드</a>에서 확인할 수 있습니다.</p></div><p>SyncSeries는 상용 소프트웨어의 신뢰성을 확보하기 위해 하드코딩된 가짜 응답을 지양하고, 실제 DB 및 네트워크 연동 환경에서 검증하는 <strong>Zero-Mock 원칙</strong>과 <strong>4-Cycle 품질 검증 프로토콜</strong>을 기본 방침으로 적용합니다.</p><hr><h2 id="_1-zero-mock-및-상용-품질-3대-원칙" tabindex="-1">1. Zero-Mock 및 상용 품질 3대 원칙 <a class="header-anchor" href="#_1-zero-mock-및-상용-품질-3대-원칙" aria-label="Permalink to “1. Zero-Mock 및 상용 품질 3대 원칙”">​</a></h2>',5)),(e(),c(g,null,{default:o(()=>[n(a,{id:"mermaid-15",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5B%22Zero-Mock%203%EB%8C%80%20%EC%9B%90%EC%B9%99%22%5D%20--%3E%20B%5B%221.%20Anti-Mock%20%26%20Full%20UI%20Spec%22%5D%0A%20%20%20%20A%20--%3E%20C%5B%222.%20Zero%20Fake%20Normalcy%22%5D%0A%20%20%20%20A%20--%3E%20D%5B%223.%20Empirical%20Verification%22%5D%0A%0A%20%20%20%20B%20-.-%3E%20B1%5B%22%ED%95%98%EB%93%9C%EC%BD%94%EB%94%A9%EB%90%9C%20Mock%20%EB%8D%B0%EC%9D%B4%ED%84%B0%20%EB%B0%B0%EC%A0%9C%2C%2030%EC%A4%84%20%EC%9D%B4%EC%83%81%EC%9D%98%20%EC%8B%A4%EC%B2%B4%ED%99%94%20UI%22%5D%0A%20%20%20%20C%20-.-%3E%20C1%5B%22%EC%9E%A5%EC%95%A0%20%EC%9D%80%ED%8F%90%20%EA%B8%88%EC%A7%80%2C%20RFC%207807%20%ED%91%9C%EC%A4%80%20%EC%97%90%EB%9F%AC%20%EC%A0%84%ED%8C%8C%22%5D%0A%20%20%20%20D%20-.-%3E%20D1%5B%22%EC%BB%B4%ED%8C%8C%EC%9D%BC%20%ED%86%B5%EA%B3%BC%EC%97%90%20%EA%B7%B8%EC%B9%98%EC%A7%80%20%EC%95%8A%EA%B3%A0%20%EC%8B%A4%EC%A0%9C%20%EC%8B%A4%ED%96%89%20%EB%A1%9C%EA%B7%B8%20%EC%9E%85%EC%A6%9D%22%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h3 id="_1-1-anti-mock-full-ui-spec-mandate" tabindex="-1">1.1 Anti-Mock &amp; Full UI Spec Mandate <a class="header-anchor" href="#_1-1-anti-mock-full-ui-spec-mandate" aria-label="Permalink to “1.1 Anti-Mock &amp; Full UI Spec Mandate”">​</a></h3><ul><li>명시적인 단위 테스트 격리 목적 외에 백엔드와 프론트엔드 실제 로직에 하드코딩된 Mock 객체, 더미 래퍼, 빈 리턴 메서드 작성을 엄격히 금지합니다.</li><li>모든 REST API와 프론트엔드 컴포넌트는 실제 데이터베이스 쿼리 및 서비스 인터페이스와 100% 연동되어야 합니다.</li><li>모든 화면 컴포넌트는 30줄 이상의 실체화된 UI 요소(테이블, 폼, 필터 등)를 갖추어야 하며, 빈 껍데기나 임시 텍스트 작성을 금지합니다.</li></ul><h3 id="_1-2-zero-fake-normalcy-가짜-정상-위장-금지" tabindex="-1">1.2 Zero Fake Normalcy (가짜 정상 위장 금지) <a class="header-anchor" href="#_1-2-zero-fake-normalcy-가짜-정상-위장-금지" aria-label="Permalink to “1.2 Zero Fake Normalcy (가짜 정상 위장 금지)”">​</a></h3><ul><li>네트워크 장애, HTTP 호출 실패, DB 쿼리 오류 발생 시 <code>catch</code> 블록에서 예외를 묵살하거나 임의의 가짜 성공 상태(<code>status: SUCCESS</code>)를 생성하여 정상 동작하는 것처럼 위장하는 행위를 차단합니다.</li><li>모든 예외는 RFC 7807 Problem Details 표준에 따라 정확한 HTTP 상태 코드와 구조화된 진단 필드를 담아 클라이언트 및 상위 관제 시스템으로 전파되어야 합니다.</li></ul><h3 id="_1-3-empirical-verification-실행-검증-필수" tabindex="-1">1.3 Empirical Verification (실행 검증 필수) <a class="header-anchor" href="#_1-3-empirical-verification-실행-검증-필수" aria-label="Permalink to “1.3 Empirical Verification (실행 검증 필수)”">​</a></h3><ul><li>단순 소스코드 수정이나 컴파일 성공에 안주하지 않고, 실제 DB 실행 로그, REST API 호출 응답, 프론트엔드 빌드 실행 결과를 콘솔에 출력하여 실증해야 합니다.</li></ul><hr><h2 id="_2-4-cycle-품질-검증-프로토콜" tabindex="-1">2. 4-Cycle 품질 검증 프로토콜 <a class="header-anchor" href="#_2-4-cycle-품질-검증-프로토콜" aria-label="Permalink to “2. 4-Cycle 품질 검증 프로토콜”">​</a></h2><p>코드 변경이 발생한 후에는 다음 4단계 회귀 검증 과정을 반복하여 빌드 무결성을 확정합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">검증 단계</th><th style="text-align:left;">주요 검증 항목</th><th style="text-align:left;">도구 및 명령어</th><th style="text-align:left;">합격 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>[Cycle 1] 전체 빌드 및 1차 검증</strong></td><td style="text-align:left;">전사 모듈 컴파일 및 타입 검증</td><td style="text-align:left;"><code>mvn compile</code>, <code>pnpm build</code></td><td style="text-align:left;">전체 빌드 성공 (BUILD SUCCESS)</td></tr><tr><td style="text-align:left;"><strong>[Cycle 2] 수정 및 2차 교차 검증</strong></td><td style="text-align:left;">인터페이스/타입 정합성 확인</td><td style="text-align:left;"><code>mvn test-compile</code></td><td style="text-align:left;">모듈 간 의존성/타입 오류 0건</td></tr><tr><td style="text-align:left;"><strong>[Cycle 3] 회귀 테스트 및 3차 검증</strong></td><td style="text-align:left;">단위/통합 테스트 및 정적 감사</td><td style="text-align:left;"><code>mvn test</code>, <code>verify-zero-mock.ps1</code></td><td style="text-align:left;">단위 테스트 통과, Mock 위반 0건</td></tr><tr><td style="text-align:left;"><strong>[Cycle 4] 최종 회귀 빌드 및 감사</strong></td><td style="text-align:left;">클린 빌드 및 독립 QA 교차 감사</td><td style="text-align:left;">Subagent Audit (<code>QA_Auditor</code>)</td><td style="text-align:left;">최종 승인 판정 (APPROVED)</td></tr></tbody></table><hr><h2 id="_3-전사-자동화-감사-스크립트-체계" tabindex="-1">3. 전사 자동화 감사 스크립트 체계 <a class="header-anchor" href="#_3-전사-자동화-감사-스크립트-체계" aria-label="Permalink to “3. 전사 자동화 감사 스크립트 체계”">​</a></h2><p>개발 산출물의 무결성을 검증하기 위해 전사 코어 에이전트 및 공통 모듈을 대상으로 3종의 전용 감사 스크립트를 운용합니다.</p><ul><li><strong><code>verify-zero-mock.ps1</code></strong>: <ul><li>Java, Vue, TypeScript 소스코드 내 하드코딩된 mock 변수, 임의의 더미 컬렉션 반환, 가짜 분기 로직을 정적 패턴 분석으로 검출.</li></ul></li><li><strong><code>verify-security-leaks.ps1</code></strong>: <ul><li>소스코드 및 설정 파일 내 평문 하드코딩된 API Key, 비밀번호, 프라이빗 인증 토큰 유출 여부 전수 스캔 (10,000+ 파일 검사).</li></ul></li><li><strong><code>verify-api-contracts.ps1</code></strong>: <ul><li>백엔드 Controller 엔드포인트와 프론트엔드 API 호출 명세 간 URL, HTTP 메서드, 파라미터 1:1 일치 여부 정합성 감사.</li></ul></li></ul><hr><h2 id="_4-전사-1-045개-테스트케이스-tc-및-playwright-e2e-ui-검증-현황-100-passed" tabindex="-1">4. 전사 1,045개 테스트케이스(TC) 및 Playwright E2E UI 검증 현황 (100% PASSED) <a class="header-anchor" href="#_4-전사-1-045개-테스트케이스-tc-및-playwright-e2e-ui-검증-현황-100-passed" aria-label="Permalink to “4. 전사 1,045개 테스트케이스(TC) 및 Playwright E2E UI 검증 현황 (100% PASSED)”">​</a></h2><p>SyncSeries 전 제품군(13개 파트 · 209개 사용 시나리오 × 5대 차원 <code>HAPPY_PATH</code> / <code>VALIDATION</code> / <code>BOUNDARY</code> / <code>STATE</code> / <code>PERMISSION</code>)에 대해 총 <strong>1,045개의 테스트 케이스(<code>L1</code>~<code>L5</code>)</strong> 및 Playwright 헤드리스 브라우저 기반 고해상도(<code>1920×1080</code>) 화면 렌더링·어노테이션 검증을 상시 수행합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">검증 항목</th><th style="text-align:left;">검증 대상</th><th style="text-align:left;">통과율 / 결과</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>전 기능 테스트케이스 (<code>L1</code>~<code>L5</code>)</strong></td><td style="text-align:left;">13개 파트 · 209개 시나리오 · 1,045개 TC</td><td style="text-align:left;"><strong><code>1,045 / 1,045 PASSED (100.0%)</code></strong></td></tr><tr><td style="text-align:left;"><strong>DB 6단계 표준 스크립트 (<code>00</code>~<code>05_*.sql</code>)</strong></td><td style="text-align:left;">9대 코어 에이전트 DB (총 54개 SQL 파일)</td><td style="text-align:left;"><strong><code>0</code> 위반 (<code>ON CONFLICT</code> 0건, <code>migrations/</code> 0건)</strong></td></tr><tr><td style="text-align:left;"><strong>Zero-Mock 정적 품질 감사</strong></td><td style="text-align:left;">18개 프로젝트 및 마이크로서비스 모듈</td><td style="text-align:left;"><strong><code>18 / 18 PASSED (0 Violations)</code></strong></td></tr><tr><td style="text-align:left;"><strong>API 계약 &amp; 시크릿 누출 감사</strong></td><td style="text-align:left;">전사 Canonical URL (<code>/api/v1/{product}/...</code>) 및 시크릿 스캔</td><td style="text-align:left;"><strong><code>11 / 11 PASSED (0 Leaks)</code></strong></td></tr><tr><td style="text-align:left;"><strong>Playwright E2E UI &amp; 고해상도 캡처</strong></td><td style="text-align:left;">전 제품군 대표 화면 <code>1920×1080</code> 원본 42종 + 콜아웃 어노테이션 40종</td><td style="text-align:left;"><strong><code>ConsoleErrors=0</code>, <code>PageErrors=0</code> (총 82종)</strong></td></tr></tbody></table><h3 id="대표-제품군-검증-화면-캡처-콜아웃-어노테이션" tabindex="-1">대표 제품군 검증 화면 캡처 (콜아웃 어노테이션) <a class="header-anchor" href="#대표-제품군-검증-화면-캡처-콜아웃-어노테이션" aria-label="Permalink to “대표 제품군 검증 화면 캡처 (콜아웃 어노테이션)”">​</a></h3><p><img src="'+y+'" alt="SyncVerse 통합 관제 대시보드" loading="lazy"></p><p><img src="'+E+'" alt="SyncBoot 엔터프라이즈 백오피스" loading="lazy"></p><p><img src="'+m+'" alt="SyncShop 8대 MSA 커머스 관제" loading="lazy"></p><p><img src="'+h+'" alt="SyncETA 자율 비전 QA 관제" loading="lazy"></p>',23))])}const D=r(C,[["render",p]]);export{S as __pageData,D as default};
